function normalAttack(){

    if(!battleActive){
        return;
    }


    const index =
        resolveAttackTargetIndex("single");


    if(index===null){
        return;
    }


    const monster =
        monsters[index];


    lungePlayerCard();


    showSkillNameBadge(
        "æ™®é€šæ”»æ“Š",
        "normal",
        0,
        index,
        [index]
    );


    const stats =
        getMainCharacterStats();


    /*
       â˜… å‘½ä¸­åˆ¤å®šï¼š
       æ‰“ç©ºçš„è©±ç›´æ¥è·³MISSã€æ’­æ”¾é–ƒé¿å‹•ç•«ï¼Œ
       ä¸è¨ˆç®—å‚·å®³ã€ä¸æ‰£è¡€ï¼Œ
       ä½†é‚„æ˜¯è¦æ­£å¸¸çµæŸé€™æ¬¡è¡Œå‹•
       ï¼ˆé€²å…¥æ€ªç‰©å›åˆï¼‰ï¼Œä¸èƒ½å¡ä½ã€‚
    */

    const hit =
        rollHitChance(
            stats.accuracy,
            getMonsterEvasion(
                monster
            ),
            getMonsterDebuffValue(
                    player,
                    "stun"
                ),
                getActiveAccuracyBonusPercent(player)
            );


    if(!hit){

        showMissEffect(
            false,
            index,
            "MISS"
        );


        addBattleLog(
            "æ™®é€šæ”»æ“Š"+
            monster.name+
            "ï¼Œæ²’æœ‰å‘½ä¸­ï¼"
        );


        updateUI();

        finishPlayerAction();

        return;

    }


    const critResult =
        rollCritical(
            player,
            "physical",
            getMonsterEffectiveAntiCrit(monster),
            monster
        );

    const damage =
        calculateDamage(
            stats.attack,
            getMonsterEffectiveDefense(monster),
            player.level,
            monster.level,
            player.element,
            monster.element,
            {
                attacker:player,
                target:monster,
                critMultiplier:critResult.multiplier
            }
        );


    monster.hp =
        Math.max(
            0,
            monster.hp-damage
        );


    showMonsterHit(
        index,
        damage,
        "hp",
        critResult.isCrit
    );


    addBattleLog(

        "æ™®é€šæ”»æ“Š"+
        monster.name+
        (
            critResult.isCrit
            ?
            "ï¼ˆçˆ†æ“Šï¼ï¼‰"
            :
            ""
        )+
        "ï¼Œé€ æˆ"+
        damage+
        "å‚·å®³ã€‚"

    );


    if(monster.hp<=0){
        killMonster(index);
    }


    updateUI();

    finishPlayerAction();

}



