function windArrowAttack(){

    if(!battleActive){
        return;
    }


    if(player.sp<10){

        if(autoBattle){

            normalAttack();

        }
        else{

            /*
               â˜… ä¿®æ­£ï¼ˆè·ŸcastDamageSkill()åŒä¸€ç¨®
               bugï¼ŒåŒä¸€æ¬¡ä¸€èµ·ä¿®æ‰ï¼‰ï¼š
               åŸæœ¬é€™è£¡ä¹Ÿæ˜¯å°å®ŒâŒè¨Šæ¯å°±ç›´æ¥returnï¼Œ
               æ²’å‘¼å«finishPlayerAction()ï¼Œæœƒè®“
               çµç®—éˆå¾é€™è£¡é–‹å§‹æ•´å€‹å¡ä½ï¼Œä¸åªé¢¨ä¹‹ç®­
               é€™æ¬¡è¡Œå‹•ï¼Œå¾Œé¢æ‰€æœ‰è§’è‰²/æ€ªç‰©çš„å›åˆ
               éƒ½ä¸æœƒå†è¢«æ¨é€²ã€‚
            */

            addBattleLog(
                "SPä¸è¶³ï¼Œç„¡æ³•ä½¿ç”¨é¢¨ä¹‹ç®­ã€‚"
            );

            finishPlayerAction();

        }

        return;

    }


    const index =
        resolveAttackTargetIndex();


    if(index===null){
        return;
    }


    player.sp -= 10;


    lungePlayerCard();


    showSkillNameBadge(
        skillDatabase.windArrow.name,
        "wind",
        0,
        index,
        [index]
    );


    setTimeout(()=>{
        showPlayerSpPopup(10);
    },500);


    const monster =
        monsters[index];


    const stats =
        getMainCharacterStats();


    const damage =
        calculateDamage(
            stats.attack+15,
            getMonsterEffectiveDefense(monster),
            player.level,
            monster.level,
            player.element,
            monster.element,
            {attacker:player,target:monster}
        );


    monster.hp =
        Math.max(
            0,
            monster.hp-damage
        );


    showMonsterHit(index,damage,"hp");


    addBattleLog(
        "é¢¨ä¹‹ç®­å‘½ä¸­"+
        monster.name+
        "ï¼Œé€ æˆ"+
        damage+
        "å‚·å®³ã€‚"
    );


    if(monster.hp<=0){
        killMonster(index);
    }


    updateUI();

    finishPlayerAction();

}


