function updateGoldDisplay(){

    const value=Math.max(0,Math.floor(Number(gold)||0));

    [
        $("homeGoldValue"),
        $("inventoryGoldValue"),
        $("v146HomeRosterGoldValue")
    ].forEach(el=>{
        if(el){
            el.textContent=value.toLocaleString("zh-TW");
        }
    });

}


