function renderAchievementContent(){

    let html=
        "";


    achievementDefinitions.forEach(
        achievement=>{

            const done=

                achievement.check();


            const claimed=

                achievementState[
                    achievement.id
                ];


            const rewardText=

                Object.keys(
                    achievement.reward
                )
                .map(
                    key=>
                        achievement.reward[key]+""
                )
                .join("ã€");


            html+=

                '<div class="home-feature-row">'+

                "<span>"+
                achievement.name+
                "<br>"+
                '<span style="font-size:11px;color:#b3a58c;">'+
                achievement.desc+
                "çå‹µï¼š"+rewardText+
                "</span>"+
                "</span>"+

                '<button class="home-feature-buy-btn"'+

                (
                    !done || claimed
                    ?
                    "disabled"
                    :
                    ""
                )+

                'onclick="claimAchievement(\''+
                achievement.id+
                '\')">'+

                (
                    claimed
                    ?
                    "å·²é ˜å–"
                    :
                    done
                    ?
                    "é ˜å–"
                    :
                    "æœªé”æˆ"
                )+

                "</button>"+

                "</div>";

        }
    );


    return html;

}


function claimAchievement(achievementId){

    const achievement=

        achievementDefinitions.find(
            a=>a.id===achievementId
        );


    if(!achievement){
        return;
    }


    if(
        !achievement.check() ||
        achievementState[achievementId]
    ){
        return;
    }


    achievementState[achievementId]=
        true;


    if(achievement.reward.gold){

        gold=
            gold+
            achievement.reward.gold;

    }

    updateGoldDisplay();

    saveGame();


    const bodyEl=
        $("homeFeatureModalBody");


    if(bodyEl){

        bodyEl.innerHTML=
            renderAchievementContent();

    }

}


